"""Independent worked answers for all 144 BC Science Physics 11 Chapter 5 entries.

Investigation answers distinguish predictions from measurements. Source-key
discrepancies and missing assumptions are explained where they affect results.
"""
from bc_kinematics_answers import paragraphs as p, parts, table

ANSWERS = {}


def answer(number, body):
    key = f'q-{number}'
    assert key not in ANSWERS
    ANSWERS[key] = body


